import React, { useState, useEffect } from 'react';
import './Cart.css'

const Cart = () => {
  const [cartItems, setCartItems] = useState([]);

  useEffect(() => {
    const storedCart = JSON.parse(localStorage.getItem('sepet')) || [];
    setCartItems(storedCart);
  }, []);

  // Sepetten ürün adetini azaltma fonksiyonu
  const decreaseQuantity = (productId) => {
    const updatedCart = cartItems.map(item => 
      item._id === productId 
        ? { ...item, adet: item.adet - 1 } 
        : item
    ).filter(item => item.adet > 0); // Adet 0'ı geçerse, ürünü sepetten çıkarır
    localStorage.setItem('sepet', JSON.stringify(updatedCart));
    setCartItems(updatedCart);
  };

  // Sepetten ürün çıkarma fonksiyonu
  const removeFromCart = (productId) => {
    const updatedCart = cartItems.filter(item => item._id !== productId);
    localStorage.setItem('sepet', JSON.stringify(updatedCart));
    setCartItems(updatedCart);
  };

  // Sepet toplam fiyatını hesaplama
  const getTotal = () => {
    return cartItems.reduce((total, item) => total + (item.price * item.adet), 0).toFixed(2);
  };

  return (
    <div className="cart">
      <h2>Sepetiniz</h2>
      {cartItems.length === 0 ? (
        <p>Sepetiniz boş.</p>
      ) : (
        <>
          <ul>
            {cartItems.map((item) => (
              <li key={item._id} className="cart-item">
                <img src={item.photo} alt={item.name} className="cart-item-image" />
                <p>{item.name}</p>
                <p>{item.price} TL</p>
                <p>Adet: {item.adet}</p>
                <button onClick={() => decreaseQuantity(item._id)}>-</button>
                <button onClick={() => removeFromCart(item._id)}>Kaldır</button>
              </li>
            ))}
          </ul>
          <div className="cart-total">
            <p>Toplam: {getTotal()} TL</p>
            <button>Ödeme Yap</button>
          </div>
        </>
      )}
    </div>
  );
};

export default Cart;
